-- 0001_initial_schema
-- Postgres (Neon) port of the original SQLite schema.
--
-- SQLite -> Postgres notes:
--   INTEGER PRIMARY KEY AUTOINCREMENT  ->  INTEGER GENERATED BY DEFAULT AS IDENTITY
--   (BY DEFAULT rather than ALWAYS so an explicit id can still be supplied when
--    importing the old gym.db rows; the app itself never sets ids by hand)

CREATE TABLE IF NOT EXISTS users (
    id   INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    name TEXT NOT NULL
);

CREATE TABLE IF NOT EXISTS categories (
    id      INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    name    TEXT NOT NULL UNIQUE,
    user_id INTEGER REFERENCES users (id) ON DELETE CASCADE
);

CREATE TABLE IF NOT EXISTS workouts (
    id      INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    date    TEXT NOT NULL,
    user_id INTEGER NOT NULL REFERENCES users (id) ON DELETE CASCADE,
    status  TEXT NOT NULL CHECK (status IN ('in_progress', 'finished'))
);

CREATE TABLE IF NOT EXISTS exercises (
    id          INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    name        TEXT NOT NULL UNIQUE,
    -- the SQLite version said "NOT NULL ... ON DELETE SET NULL", which can never
    -- succeed; deleting a category now removes its exercises instead
    category_id INTEGER NOT NULL REFERENCES categories (id) ON DELETE CASCADE
);

CREATE TABLE IF NOT EXISTS sets (
    id          INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    workout_id  INTEGER NOT NULL REFERENCES workouts (id) ON DELETE CASCADE,
    exercise_id INTEGER NOT NULL REFERENCES exercises (id) ON DELETE CASCADE,
    reps        INTEGER NOT NULL,
    weight      INTEGER NOT NULL,
    note        TEXT
);

-- Postgres does not index foreign keys automatically the way it indexes primary keys,
-- and every one of these columns is filtered on or cascaded through
CREATE INDEX IF NOT EXISTS idx_categories_user_id ON categories (user_id);
CREATE INDEX IF NOT EXISTS idx_workouts_user_id ON workouts (user_id);
CREATE INDEX IF NOT EXISTS idx_exercises_category_id ON exercises (category_id);
CREATE INDEX IF NOT EXISTS idx_sets_workout_id ON sets (workout_id);
CREATE INDEX IF NOT EXISTS idx_sets_exercise_id ON sets (exercise_id);
